const r = await tools.exec_command({cmd:"python - <<'PY'
import json,numpy as np
D=json.load(open('data/calibration.json'))
# candidate from prior

def ev(e):
 F=np.array(e['deformation'],float); n=np.array(e['direction'],float); n/=np.linalg.norm(n); H=np.linalg.inv(F).T; l=np.log(np.linalg.det(F));I=np.trace(F.T@F);B=F@F.T;C=F.T@F;d=np.eye(3)
 A=.6*np.einsum('ij,ab->iajb',d,d)+.2*(4*np.einsum('ia,jb->iajb',F,F)-2*np.einsum('ib,ja->iajb',F,F)+2*np.einsum('ij,ab->iajb',I*d-B,d)-2*np.einsum('ij,ab->iajb',d,C))
 co=2*l-1.4;A+=2*np.einsum('ia,jb->iajb',H,H)-co*np.einsum('ib,ja->iajb',H,H)
 N=F.T@n;return np.linalg.eigvalsh(np.einsum('iajb,a,b->ij',A,N,N))
y=np.array([r['value'] for r in D]); br=np.array([r['input']['branch'] for r in D]); base=np.array([np.sqrt(1000*ev(r['input'])[br[i]]) for i,r in enumerate(D)])
for m in [1.17,1.1695,1.0817]:
 res=(np.sqrt(m)*base-y)/.02
 print(m,'mean',np.mean(res**2),'first',np.mean(res[:40]**2),'later',np.mean(res[40:]**2), 'range',res.min(),res.max())
for i in range(0,216,24): print(i, np.sqrt(1.17)*base[i],y[i],base[i])
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":10000});
text(r.output);

